    "symfony/console": "^8.1",
    "symfony/dotenv": "^8.1",
    "symfony/error-handler": "^8.1",
    "symfony/form": "^8.1",
    "symfony/framework-bundle": "^8.1",
    "symfony/process": "^8.1",
    "symfony/runtime": "^8.1",
    "symfony/security-bundle": "^8.1",
    "symfony/serializer": "^8.1",
    "symfony/twig-bundle": "^8.1",
    "symfony/validator": "^8.1",
    "symfony/yaml": "^8.1",
    "collectioning/collection": "dev-master",
    "cruding/crud": "dev-master",
    "easycorp/easyadmin-bundle": "^5.5",
    "interfacing/interface": "dev-master",
    "objecting/object": "dev-master",
    "tabling/table": "dev-master",
    "viewing/view": "dev-master"
  },
  "require-dev": {
    "doctrine/doctrine-fixtures-bundle": "^4.3",
    "friendsofphp/php-cs-fixer": "^3.95.4",
    "gating/gate": "dev-master",
    "phpstan/phpstan": "^2.2",
    "phpunit/phpunit": "^11.5.55",
    "symfony/panther": "^2.2",
    "symfony/phpunit-bridge": "^8.1",
    "symfony/test-pack": "^1.2"
  },
  "autoload": {
    "psr-4": {
      "App\\Temporaring\\": "src/"
    }
  },
  "autoload-dev": {
    "psr-4": {
      "App\\Temporaring\\Tests\\": "tests/"
    }
  },
  "scripts": {
    "lint:php": "php -l src/Kernel.php && php -l src/TemporaringBundle.php && php -l bin/console && php -l public/index.php",
    "lint:yaml": "php bin/console lint:yaml config --parse-tags",
    "lint:container": "php bin/console lint:container",
    "cs:check": "php-cs-fixer fix --dry-run --diff --verbose",
    "cs:fix": "php-cs-fixer fix --verbose",
    "phpstan": "phpstan analyse --memory-limit=1G",
    "schema:validate": [
      "@putenv DATABASE_URL=sqlite:///:memory:",
      "@putenv INFRA_DATABASE_URL=sqlite:///:memory:",
      "php bin/console doctrine:schema:validate --skip-sync --env=test"
    ],
    "migrations:up-to-date": [
      "@putenv DATABASE_URL=sqlite:///:memory:",
      "@putenv INFRA_DATABASE_URL=sqlite:///:memory:",
      "php bin/console doctrine:migrations:up-to-date --env=test"
    ],
    "schema:parity": [
      "@schema:validate",
      "@migrations:up-to-date"
    ],
    "gating": "php vendor/bin/gating check --target=. --profile=config/tempo_gating_profile.yaml --rule-set=config/tempo_gating_rules.yaml --policy-root=vendor/gating/gate/.gating --severity-config=vendor/gating/gate/.gating/config/severity.yaml",
    "test": "phpunit --configuration phpunit.xml.dist",
    "test:coverage": [
      "@php -r \"if (!is_dir('var/coverage')) { mkdir('var/coverage', 0777, true); }\"",
      "@php -d xdebug.mode=coverage vendor/bin/phpunit --configuration phpunit.xml.dist --path-coverage --coverage-text=var/coverage/summary.txt"
    ],
    "gate": "@php vendor/bin/gating check --target=.",
    "quality": [
      "@cs:check",
      "@phpstan",
      "@test",
      "@gate"
    ]
  },
  "config": {
    "allow-plugins": {
      "symfony/runtime": true
    }
  },
  "repositories": [
    {
      "type": "path",
      "url": "../Gating",
      "options": {
        "symlink": true,
        "versions": {
          "gating/gate": "dev-master"
        }
      }
    },
    {
      "type": "path",
      "url": "../Cruding",
